const test=require('node:test'),assert=require('node:assert/strict');
const {messengerTask,messengerStep}=require('../src/messenger-task.cjs'),{taskFor,taskTools}=require('../src/agent-task.cjs');
const tools=['notes','chats','search','prepare'].map(name=>({name:'gyomu_cbe_'+name,parameters:{type:'object',properties:{operation:{type:'string'},id:{type:'string'},limit:{type:'integer'},box:{type:'string'},name:{type:'string'},scope:{type:'string'},kind:{type:'string'},body:{type:'string'},title:{type:'string'}},required:[]}}));
function pair(name,args,value,id){return [{type:'function_call',name,arguments:JSON.stringify(args),call_id:id},{type:'function_call_output',call_id:id,output:JSON.stringify(value)}];}
test('CBE routing does not mistake a no-send instruction for permission and excludes document tools',()=>{const task=taskFor('CBE_CLI로 받은 쪽지 최신 3건의 본문을 요약해 줘. 쪽지나 대화를 보내거나 수정하지 마.');assert.equal(task.area,'cbe');assert.equal(task.send,false);assert.equal(task.observe,false);assert(!taskTools(task,[...tools,{name:'edit_document'}]).some(t=>t.name==='edit_document'));});
test('chat summary remains chat when a trailing instruction prohibits notes',()=>{const task=messengerTask('CBE 대화 최신 1개 요약. 대화와 쪽지를 보내지 마.');assert.equal(task.kind,'chat');assert.equal(task.send,false);assert.equal(messengerStep(task,[],tools).tools[0].name,'gyomu_cbe_chats');});
test('summary requires every actual message body before final model synthesis',()=>{const task=messengerTask('CBE 쪽지 최신 2건 요약'),input=pair('gyomu_cbe_notes',{operation:'list'},{items:[{id:'n1'},{id:'n2'}]},'a');let step=messengerStep(task,input,tools);assert.equal(step.required,true);assert.deepEqual(step.tools[0].parameters.properties.id.enum,['n1','n2']);input.push(...pair('gyomu_cbe_notes',{operation:'read',id:'n1'},{id:'n1',text:'합성 본문1'},'b'));step=messengerStep(task,input,tools);assert.deepEqual(step.tools[0].parameters.properties.id.enum,['n2']);input.push(...pair('gyomu_cbe_notes',{operation:'read',id:'n2'},{id:'n2',text:'합성 본문2'},'c'));step=messengerStep(task,input,tools);assert.equal(step.context.documents.length,2);assert.deepEqual(step.tools,[]);});
test('send is constrained to observed name and organization, then a single verified result',()=>{const task=messengerTask('CBE 쪽지를 가상초등학교 가상교사 선생님에게 보내줘. 본문은 "합성 테스트"'),input=pair('gyomu_cbe_search',{name:'가상교사'},{items:[{id:'p1',name:'가상교사',department:'다른초등학교'},{id:'p2',name:'가상교사',department:'교육청>가상초등학교'}]},'a');assert.equal(task.recipient,'가상교사');let step=messengerStep(task,input,tools);assert.deepEqual(step.tools[0].parameters.properties.recipient_ids.items.enum,['p2']);assert.deepEqual(step.tools[0].parameters.properties.body.enum,['합성 테스트']);input.push(...pair('gyomu_cbe_prepare',{kind:'note'},{ok:true,result:{sent:true,verified:true}},'b'));assert.match(messengerStep(task,input,tools).receipt,/전송/);input.at(-1).output=JSON.stringify({error:'전송 확인 실패'});step=messengerStep(task,input,tools);assert.deepEqual(step.tools,[]);assert.match(step.instructions,/재전송하지/);});

test('asking for a CBE procedure reads its skill without querying real messages',()=>{const task=taskFor('CBE 업무 절차'),step=messengerStep(task,[],[...tools,{name:'gyomu_skill_read',parameters:{type:'object',properties:{area:{type:'string'}},required:[]}}]);assert.equal(task.explain,true);assert.equal(step.tools[0].name,'gyomu_skill_read');assert.equal(step.required,true);});
